async function resolve(qname, qtype, fromClientIp) {
  let servers = ROOT_SERVERS;
  while (true) {
    // ask the current server, requesting recursion
    const resp = await query(servers[0], qname, qtype, { RD: 1 });

    if (resp.answer.length) {
      return resp.answer;          // got the records
    }

    // referral: take the NS names from the Authority section
    const nsNames = resp.authority
      .filter(r => r.type === 'NS')
      .map(r => r.target);

    // resolve each nameserver's address from scratch
    servers = await Promise.all(nsNames.map(n => resolve(n, 'A', fromClientIp)));
  }
}
